-- Remove only the temporary records generated by the production smoke test.
DELETE FROM conversations c
WHERE c.company_id = (SELECT id FROM companies WHERE slug = 'empresa-demo')
  AND c.created_at >= TIMESTAMPTZ '2026-09-02 00:00:00+00'
  AND EXISTS (
    SELECT 1 FROM messages m
    WHERE m.company_id = c.company_id
      AND m.conversation_id = c.id
      AND m.body LIKE 'QA automatizado peopleX %'
  );

DELETE FROM users
WHERE company_id = (SELECT id FROM companies WHERE slug = 'empresa-demo')
  AND email LIKE 'qa.peoplex.%@example.invalid';

DELETE FROM auth.users
WHERE email LIKE 'qa.peoplex.%@example.invalid';
